<?php $stmt=$pdo->prepare('SELECT * FROM notifications WHERE user_id IS NULL OR user_id=? ORDER BY created_at DESC LIMIT 100');$stmt->execute([current_user()['id']]);$rows=$stmt->fetchAll();$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id IS NULL OR user_id=?')->execute([current_user()['id']]); ?>
